export function createStore() {
  const staff = seedStaff();
  const aduan = seedAduan();
  const kawasan = seedKawasan();
  const serviceCenters = seedServiceCenters();
  const caseGroups = seedCaseGroups();
  const citizens = seedCitizens();

  const today = () => new Date().toISOString().slice(0, 10);
  const audit = (item, by, action, detail) => {
    item.history.push({ by, at: today(), action, detail });
  };

  // Expiry / deactivation returns claimed aduan to the pool.
  const releaseHeld = (staffId, by, reason) => {
    for (const a of aduan) {
      if (a.assigneeId === staffId) {
        a.assigneeId = null;
        audit(a, by, "release", reason);
      }
    }
  };

  return {
    listStaff: () => staff.map((s) => ({ ...s })),
    getStaff: (id) => staff.find((s) => s.id === id) ?? null,
    getStaffByEmail: (email) =>
      staff.find((s) => s.email.toLowerCase() === String(email).toLowerCase()) ?? null,
    addStaff: ({ name, role, email, expiresAt }) => {
      const s = {
        id: `u-${Date.now()}`,
        name: name ?? email.split("@")[0],
        role,
        email,
        active: true,
        expiresAt: expiresAt || null,
        initials: String(email).slice(0, 2).toUpperCase(),
        service_center_id: SERVICE_CENTER_ID,
      };
      staff.push(s);
      return { ...s };
    },
    setStaffActive: (id, active, by) => {
      const s = staff.find((x) => x.id === id);
      if (!s) return null;
      s.active = active;
      if (!active) releaseHeld(id, by, `${s.name} deactivated, released to pool`);
      return { ...s };
    },
    sweepExpired: (by = "system", now = new Date()) => {
      let count = 0;
      for (const s of staff) {
        if (s.expiresAt && new Date(s.expiresAt) < now) {
          const held = aduan.filter((a) => a.assigneeId === s.id).length;
          releaseHeld(s.id, by, `${s.name} expired, released to pool`);
          count += held;
        }
      }
      return count;
    },
    listAduan: () => aduan.map((a) => ({ ...a, history: [...a.history] })),
    getAduan: (id) => {
      const a = aduan.find((x) => x.id === Number(id));
      return a ? { ...a, history: [...a.history] } : null;
    },
    mutateAduan: (id, fn) => {
      const a = aduan.find((x) => x.id === Number(id));
      if (!a) return null;
      fn(a, { audit });
      return { ...a, history: [...a.history] };
    },
    listCitizens: () => citizens.map((c) => ({ ...c })),
    getCitizen: (id) => citizens.find((c) => c.id === String(id)) ?? null,
    getKawasan: () => ({ ...kawasan }),
    listServiceCenters: () => serviceCenters.map((s) => ({ ...s })),
    getServiceCenter: (id) => serviceCenters.find((s) => s.id === id) ?? null,
    listCaseGroups: () => caseGroups.map((g) => ({
      ...g,
      memberIds: aduan.filter((a) => a.case_group_id === g.id).map((a) => a.id),
    })),
    getCaseGroup: (id) => {
      const g = caseGroups.find((x) => x.id === String(id));
      if (!g) return null;
      return {
        ...g,
        memberIds: aduan.filter((a) => a.case_group_id === g.id).map((a) => a.id),
      };
    },
    createCaseGroup: ({ title, category, owner_staff_id }) => {
      const g = {
        id: `cg-${Date.now()}`,
        title,
        category: category ?? "Isu Lain",
        status: "Open",
        owner_staff_id,
      };
      caseGroups.push(g);
      return { ...g, memberIds: [] };
    },
  };
}
